package com.wangc.bill.reference;

import android.content.ContentValues;
import android.content.Context;
import android.content.SharedPreferences;
import android.os.SystemClock;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import java.util.List;
import java.util.function.BooleanSupplier;
import org.json.JSONObject;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

/** Real raw Transfer SQLite feed into the existing credit worker; not Transfer command/UI parity. */
@RunWith(AndroidJUnit4.class)
public final class OriginalTransferCreditDeviceTest {
    private static final String DATABASE="reference_original_transfer_credit_test.sqlite";
    private Context context;private ReferenceStore store;private SharedPreferences preferences;private long oldBook;
    private long january,february;
    @Before public void open(){context=ApplicationProvider.getApplicationContext();context.deleteDatabase(DATABASE);store=new ReferenceStore(context,DATABASE);store.getWritableDatabase();preferences=context.getSharedPreferences("reference_settings",Context.MODE_PRIVATE);oldBook=preferences.getLong("current_book",1);preferences.edit().putLong("current_book",store.books().get(0).optLong("id")).commit();january=OriginalInstalmentSchedule.parse("2025-01-15","yyyy-MM-dd");february=OriginalInstalmentSchedule.parse("2025-02-15","yyyy-MM-dd");}
    @After public void close(){if(store!=null)store.close();preferences.edit().putLong("current_book",oldBook).commit();context.deleteDatabase(DATABASE);}
    private void await(BooleanSupplier condition){long until=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<until){if(condition.getAsBoolean())return;SystemClock.sleep(25);}assertTrue("Actual Transfer credit rebuild timed out",condition.getAsBoolean());}
    private long credit(int owner,long semantic,double number){AssetRepository.Definition d=new AssetRepository.Definition("合成转账信用账户 "+semantic,2,null);d.assetNumber=number;d.outAccountDate="每月1号";d.inAccountDate="出账日1";return store.assetRepository().insertRecovered(owner,semantic,1,0,d);}
    private OriginalTransferRecord transfer(int owner,long semantic,long from,long to,double cost,double toCost,long time){OriginalTransferRecord row=new OriginalTransferRecord();row.userId=owner;row.transferId=semantic;row.fromAssetId=from;row.toAssetId=to;row.cost=cost;row.toCost=toCost;row.time=time;row.remark="合成原版转账";new OriginalTransferRepository(store).saveOriginalRaw(row);return row;}
    private void initialReady(int owner,int bookOwner,long semantic){await(()->OriginalFinancialEffects.creditStatus(store,owner,bookOwner,semantic)==OriginalFinancialEffects.CreditStatus.READY);}
    private void rebuild(int owner,int bookOwner,long semantic){initialReady(owner,bookOwner,semantic);long before=OriginalFinancialEffects.creditRevision(store,owner,bookOwner,semantic);new OriginalFinancialEffects(store,owner,bookOwner).creditRefresh(semantic);await(()->OriginalFinancialEffects.creditStatus(store,owner,bookOwner,semantic)==OriginalFinancialEffects.CreditStatus.READY&&OriginalFinancialEffects.creditRevision(store,owner,bookOwner,semantic)>before);}
    private List<OriginalCreditBill> statements(int owner,int bookOwner,long semantic){return OriginalFinancialEffects.creditStatements(store,owner,bookOwner,semantic);}
    private OriginalBillRecord fee(long asset,int semantic,double number){OriginalBillRecord row=new OriginalBillRecord();row.userId=0;row.billId=semantic;row.assetId=asset;row.cost=number;row.time=january;row.bookId=store.book(store.books().get(0).optLong("id")).optLong("semantic_id");row.parentCategoryId=99;row.childCategoryId=-1;row.remark="合成独立手续费";ContentValues p=new ContentValues();p.put("book_id",store.books().get(0).optLong("id"));p.put("kind","expense");p.put("amount",Math.round(number*100));p.put("currency","CNY");p.put("category_id",store.categoryRepository().parent(99).optLong("id"));p.put("time",january);p.put("created",january);new OriginalBillRepository(store).saveOriginalRaw(row,p);return row;}

    @Test public void actualFeedKeepsOwnerEitherEndpointOrderAndRawDeletedRowsWithoutBookOrHideFiltering(){long endpoint=9000000099L;AssetRepository.Definition hidden=new AssetRepository.Definition("隐藏别本信用账户",2,null);hidden.hide=true;hidden.showBook.add(9999L);store.assetRepository().insertRecovered(7,endpoint,1,0,hidden);OriginalTransferRecord first=transfer(7,9000000001L,endpoint,199,-12.125,7,january+200);first.originalDeleted=true;new OriginalTransferRepository(store).saveOriginalRaw(first);transfer(7,9000000002L,299,endpoint,5,4,january+100);transfer(8,9000000001L,endpoint,199,100,100,january+300);transfer(7,9000000003L,41,42,100,100,january+400);transfer(7,9000000004L,0,999,.5,.5,january);List<OriginalCreditProjection.Transfer> read=new OriginalCreditDataSource(store,7).transfers(endpoint);assertEquals(2,read.size());assertEquals(january+200,read.get(0).time);assertEquals(-12.125,read.get(0).cost,0);assertEquals(endpoint,read.get(0).fromAssetId);assertEquals(199,read.get(0).toAssetId);assertEquals(january+100,read.get(1).time);assertEquals(endpoint,read.get(1).toAssetId);assertEquals(1,new OriginalCreditDataSource(store,7).transfers(0).size());assertNotEquals(first.transferId,first.localRowId);assertTrue(new OriginalCreditDataSource(store,0).transfers(endpoint).isEmpty());}
    @Test public void persistedTransferCostDrivesBothCreditDirectionsAndAnIndependentFeeAppearsOnce(){long from=credit(0,99,-12),to=credit(0,199,-3);OriginalBillRecord charge=fee(99,456,2);OriginalTransferRecord row=transfer(0,9000000001L,99,199,-10,7,january);row.billId=charge.billId;row.serviceCharge=2;new OriginalTransferRepository(store).saveOriginalRaw(row);rebuild(0,0,99);rebuild(0,0,199);OriginalCreditBill outgoing=statements(0,0,99).get(0),incoming=statements(0,0,199).get(0);assertEquals(12,outgoing.getNumber(),0);assertEquals(12,outgoing.getRemindNumber(),0);assertEquals(2,outgoing.getBillInfoList().size());assertEquals(-2,outgoing.getBillInfoList().get(0).getNumber(),0);assertEquals(-10,outgoing.getBillInfoList().get(1).getNumber(),0);assertEquals(0,outgoing.getBillInfoList().get(1).getBillId());assertEquals(-10,incoming.getNumber(),0);assertEquals(10,incoming.getBillInfoList().get(0).getNumber(),0);assertEquals(0,incoming.getBillInfoList().get(0).getBillId());assertEquals(7,row.getCurrencyCost(199),0);assertEquals(-12,store.assetRepository().byRowId(from).optDouble("asset_number"),0);assertEquals(-3,store.assetRepository().byRowId(to).optDouble("asset_number"),0);assertTrue(new OriginalCreditDataSource(store,0).receipts(99).isEmpty());assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));assertEquals(1,store.scalar("SELECT COUNT(*) n FROM transactions"));}
    @Test public void aBookOwnerContextNeverExpandsTheTransferFeedsCurrentUserPredicate(){credit(7,99,-3);credit(8,99,-90);transfer(7,1,99,200,3,3,january);transfer(8,1,99,200,90,90,january);rebuild(7,8,99);OriginalCreditBill bill=statements(7,8,99).get(0);assertEquals(3,bill.getNumber(),0);assertEquals(1,bill.getBillInfoList().size());assertEquals(-3,bill.getBillInfoList().get(0).getNumber(),0);assertEquals(-3,store.assetRepository().p(99,7).optDouble("asset_number"),0);assertEquals(-90,store.assetRepository().p(99,8).optDouble("asset_number"),0);}
    @Test public void transferTimeSelectsTheActualStatementMonthAndReturnsNewestFirst(){credit(0,99,-5);transfer(0,1,99,200,2,2,january);transfer(0,2,99,200,3,3,february);rebuild(0,0,99);List<OriginalCreditBill> bills=statements(0,0,99);assertEquals(2,bills.size());assertEquals(2,bills.get(0).getMonth());assertEquals(3,bills.get(0).getNumber(),0);assertEquals(february,bills.get(0).getBillInfoList().get(0).getDate());assertEquals(1,bills.get(1).getMonth());assertEquals(2,bills.get(1).getNumber(),0);assertEquals(january,bills.get(1).getBillInfoList().get(0).getDate());}
    @Test public void rawStorageDoesNotInventAPostSaveCreditRefreshOrReplayAnAssetDelta(){long account=credit(0,99,-20);OriginalTransferRecord row=transfer(0,1,99,200,10,7,january);initialReady(0,0,99);long before=OriginalFinancialEffects.creditRevision(store,0,0,99);assertEquals(10,statements(0,0,99).get(0).getNumber(),0);row.cost=15;new OriginalTransferRepository(store).saveOriginalRaw(row);assertEquals(15,new OriginalCreditDataSource(store,0).transfers(99).get(0).cost,0);assertEquals(before,OriginalFinancialEffects.creditRevision(store,0,0,99));assertEquals(10,statements(0,0,99).get(0).getNumber(),0);rebuild(0,0,99);assertEquals(15,statements(0,0,99).get(0).getNumber(),0);assertEquals(-20,store.assetRepository().byRowId(account).optDouble("asset_number"),0);assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));}
    @Test public void restoredTransferRowsRebuildCreditWithoutReplayingBalancesOrHistories(){long account=credit(0,99,-5);OriginalTransferRecord row=transfer(0,9000000001L,99,200,5,2,january);rebuild(0,0,99);JSONObject backup=store.backup();row.cost=9;new OriginalTransferRepository(store).saveOriginalRaw(row);rebuild(0,0,99);assertEquals(9,statements(0,0,99).get(0).getNumber(),0);store.restore(backup);rebuild(0,0,99);assertEquals(5,new OriginalCreditDataSource(store,0).transfers(99).get(0).cost,0);assertEquals(5,statements(0,0,99).get(0).getNumber(),0);assertEquals(-5,store.assetRepository().byRowId(account).optDouble("asset_number"),0);assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));assertEquals(1,store.scalar("SELECT COUNT(*) n FROM original_transfers"));assertEquals(0,store.scalar("SELECT COUNT(*) n FROM transactions"));}
}
